/*
** Sample App Runloop
*/
while (CFE_ES_RunLoop(&SAMPLE_APP_Data.RunStatus) == true)
{
    /*
    ** Performance Log Exit Stamp
    */
    CFE_ES_PerfLogExit(SAMPLE_APP_PERF_ID);

    /* Pend on receipt of command packet */
    status = CFE_SB_ReceiveBuffer(&SBBufPtr, SAMPLE_APP_Data.CommandPipe, CFE_SB_PEND_FOREVER);

    /*
    ** Performance Log Entry Stamp
    */
    CFE_ES_PerfLogEntry(SAMPLE_APP_PERF_ID);

    if (status == CFE_SUCCESS)
    {
        SAMPLE_APP_TaskPipe(SBBufPtr);
    }
    else
    {
        CFE_EVS_SendEvent(SAMPLE_APP_PIPE_ERR_EID,
                          CFE_EVS_EventType_ERROR,
                          "SAMPLE APP: SB Pipe Read Error, App Will Exit");

        SAMPLE_APP_Data.RunStatus = CFE_ES_RunStatus_APP_ERROR;
    }
}

/*
** Performance Log Exit Stamp
*/
CFE_ES_PerfLogExit(SAMPLE_APP_PERF_ID);

CFE_ES_ExitApp(SAMPLE_APP_Data.RunStatus);

     ** Initialize housekeeping packet (clear user data area).
     */
    CFE_MSG_Init(CFE_MSG_PTR(SAMPLE_APP_Data.HkTlm.TelemetryHeader),
                 CFE_SB_ValueToMsgId(SAMPLE_APP_HK_TLM_MID),
                 sizeof(SAMPLE_APP_Data.HkTlm));

    /*
     ** Create Software Bus message pipe.
     */
    status = CFE_SB_CreatePipe(&SAMPLE_APP_Data.CommandPipe,
                               SAMPLE_APP_PLATFORM_PIPE_DEPTH,
                               SAMPLE_APP_PLATFORM_PIPE_NAME);
    if (status != CFE_SUCCESS)
    {
        CFE_EVS_SendEvent(SAMPLE_APP_CR_PIPE_ERR_EID,
                          CFE_EVS_EventType_ERROR,
                          "Sample App: Error creating SB Command Pipe, RC = 0x%08lX",
                          (unsigned long)status);
    }
}

if (status == CFE_SUCCESS)
{
    /*
    ** Subscribe to Housekeeping request commands
    */
    status = CFE_SB_Subscribe(CFE_SB_ValueToMsgId(SAMPLE_APP_SEND_HK_MID), SAMPLE_APP_Data.CommandPipe);
    if (status != CFE_SUCCESS)
    {
        CFE_EVS_SendEvent(SAMPLE_APP_SUB_HK_ERR_EID,
                          CFE_EVS_EventType_ERROR,
                          "Sample App: Error Subscribing to HK request, RC = 0x%08lX",
                          (unsigned long)status);
    }
}

if (status == CFE_SUCCESS)
{
    /*
    ** Subscribe to ground command packets
    */
    status = CFE_SB_Subscribe(CFE_SB_ValueToMsgId(SAMPLE_APP_CMD_MID), SAMPLE_APP_Data.CommandPipe);
    if (status != CFE_SUCCESS)
    {
        CFE_EVS_SendEvent(SAMPLE_APP_SUB_CMD_ERR_EID,
                          CFE_EVS_EventType_ERROR,
                          "Sample App: Error Subscribing to Commands, RC = 0x%08lX",
                          (unsigned long)status);

static CFE_SB_MsgId_t CMD_MID     = CFE_SB_MSGID_RESERVED;
static CFE_SB_MsgId_t SEND_HK_MID = CFE_SB_MSGID_RESERVED;

CFE_SB_MsgId_t MsgId = CFE_SB_INVALID_MSG_ID;

/* cache the local MID Values here, this avoids repeat lookups */
if (!CFE_SB_IsValidMsgId(CMD_MID))
{
    CMD_MID     = CFE_SB_ValueToMsgId(SAMPLE_APP_CMD_MID);
    SEND_HK_MID = CFE_SB_ValueToMsgId(SAMPLE_APP_SEND_HK_MID);
}

CFE_MSG_GetMsgId(&SBBufPtr->Msg, &MsgId);

/* Process all SB messages */
if (CFE_SB_MsgId_Equal(MsgId, SEND_HK_MID))
{
    /* Housekeeping request */
    SAMPLE_APP_SendHkCmd((const SAMPLE_APP_SendHkCmd_t *)SBBufPtr);
}
else if (CFE_SB_MsgId_Equal(MsgId, CMD_MID))
{
    /* Ground command */
    SAMPLE_APP_ProcessGroundCommand(SBBufPtr);

{
    CFE_MSG_FcnCode_t CommandCode = 0;

    CFE_MSG_GetFcnCode(&SBBufPtr->Msg, &CommandCode);

    /*
    ** Process SAMPLE app ground commands
    */
    switch (CommandCode)
    {
        case SAMPLE_APP_NOOP_CC:
            if (SAMPLE_APP_VerifyCmdLength(&SBBufPtr->Msg, sizeof(SAMPLE_APP_NoopCmd_t)))
            {
                SAMPLE_APP_NoopCmd((const SAMPLE_APP_NoopCmd_t *)SBBufPtr);
            }
            break;

        case SAMPLE_APP_RESET_COUNTERS_CC:
            if (SAMPLE_APP_VerifyCmdLength(&SBBufPtr->Msg, sizeof(SAMPLE_APP_ResetCountersCmd_t)))
            {
                SAMPLE_APP_ResetCountersCmd((const SAMPLE_APP_ResetCountersCmd_t *)SBBufPtr);
            }
            break;

        case SAMPLE_APP_PROCESS_CC:
            if (SAMPLE_APP_VerifyCmdLength(&SBBufPtr->Msg, sizeof(SAMPLE_APP_ProcessCmd_t)))
            {
                SAMPLE_APP_ProcessCmd((const SAMPLE_APP_ProcessCmd_t *)SBBufPtr);
            }
            break;

        case SAMPLE_APP_DISPLAY_PARAM_CC:
            if (SAMPLE_APP_VerifyCmdLength(&SBBufPtr->Msg, sizeof(SAMPLE_APP_DisplayParamCmd_t)))
            {
                SAMPLE_APP_DisplayParamCmd((const SAMPLE_APP_DisplayParamCmd_t *)SBBufPtr);
            }
            break;

        default:
            CFE_EVS_SendEvent(SAMPLE_APP_CC_ERR_EID,
                              CFE_EVS_EventType_ERROR,
                              "Invalid ground command code: CC = %d",
                              CommandCode);
            break;
    }
}

/* SAMPLE NOOP commands                                                       */
/*                                                                            */
/* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * **/
CFE_Status_t SAMPLE_APP_NoopCmd(const SAMPLE_APP_NoopCmd_t *Msg)
